PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS profiles (user_id TEXT PRIMARY KEY, display_name TEXT NOT NULL DEFAULT '', timezone TEXT NOT NULL DEFAULT 'Asia/Bangkok', theme TEXT NOT NULL DEFAULT 'system' CHECK(theme IN ('light','dark','system')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_preferences (user_id TEXT PRIMARY KEY, hidden_mode INTEGER NOT NULL DEFAULT 0 CHECK(hidden_mode IN (0,1)), dashboard_cards_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(dashboard_cards_json)), health_kinds_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(health_kinds_json)), water_goal_ml INTEGER NOT NULL DEFAULT 2000 CHECK(water_goal_ml >= 0), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS savings_goals (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 160), target_satang INTEGER NOT NULL CHECK(target_satang > 0), due_date TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','done','archived')), color TEXT NOT NULL DEFAULT 'green', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_savings_goals_owner_status ON savings_goals(user_id,status);
CREATE TABLE IF NOT EXISTS savings_transactions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, goal_id TEXT, kind TEXT NOT NULL CHECK(kind IN ('deposit','withdraw','opening')), amount_satang INTEGER NOT NULL CHECK(amount_satang > 0), entry_date TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(goal_id) REFERENCES savings_goals(id) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS idx_savings_transactions_owner_date ON savings_transactions(user_id,entry_date DESC);
CREATE INDEX IF NOT EXISTS idx_savings_transactions_goal ON savings_transactions(user_id,goal_id,entry_date DESC);
CREATE TABLE IF NOT EXISTS health_preferences (user_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('weight','pressure','sleep','water','symptom')), enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)), PRIMARY KEY(user_id,kind));
CREATE TABLE IF NOT EXISTS health_entries (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('weight','pressure','sleep','water','symptom')), measured_at TEXT NOT NULL, weight_kg REAL, systolic INTEGER, diastolic INTEGER, pulse_bpm INTEGER, sleep_started_at TEXT, sleep_ended_at TEXT, water_ml INTEGER, symptom_title TEXT, symptom_level INTEGER CHECK(symptom_level BETWEEN 1 AND 5), value_text TEXT NOT NULL DEFAULT '', details TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK((kind='weight' AND weight_kg IS NOT NULL AND weight_kg > 0) OR kind!='weight'), CHECK((kind='pressure' AND systolic IS NOT NULL AND diastolic IS NOT NULL) OR kind!='pressure'), CHECK((kind='water' AND water_ml IS NOT NULL AND water_ml >= 0) OR kind!='water'));
CREATE INDEX IF NOT EXISTS idx_health_entries_owner_kind_date ON health_entries(user_id,kind,measured_at DESC);
CREATE TABLE IF NOT EXISTS notes (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL DEFAULT 'ไม่มีชื่อ', body TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL CHECK(kind IN ('note','diary')), entry_date TEXT NOT NULL, mood TEXT NOT NULL DEFAULT '', pinned INTEGER NOT NULL DEFAULT 0 CHECK(pinned IN (0,1)), archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), version INTEGER NOT NULL DEFAULT 1 CHECK(version > 0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_notes_owner_updated ON notes(user_id,archived,pinned,updated_at DESC);
CREATE TABLE IF NOT EXISTS note_tags (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, note_id TEXT NOT NULL, tag TEXT NOT NULL CHECK(length(tag) BETWEEN 1 AND 60), UNIQUE(note_id,tag), FOREIGN KEY(note_id) REFERENCES notes(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_note_tags_owner_tag ON note_tags(user_id,tag);
CREATE TABLE IF NOT EXISTS split_bills (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL CHECK(length(title) BETWEEN 1 AND 160), bill_date TEXT NOT NULL, restaurant TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','settling','settled')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_split_bills_owner_date ON split_bills(user_id,bill_date DESC);
CREATE TABLE IF NOT EXISTS split_participants (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, bill_id TEXT NOT NULL, name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 100), is_me INTEGER NOT NULL DEFAULT 0 CHECK(is_me IN (0,1)), FOREIGN KEY(bill_id) REFERENCES split_bills(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_split_participants_bill ON split_participants(user_id,bill_id);
CREATE TABLE IF NOT EXISTS split_expenses (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, bill_id TEXT NOT NULL, title TEXT NOT NULL, amount_satang INTEGER NOT NULL CHECK(amount_satang > 0), split_method TEXT NOT NULL DEFAULT 'equal' CHECK(split_method IN ('equal','fixed','percent')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(bill_id) REFERENCES split_bills(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_split_expenses_bill ON split_expenses(user_id,bill_id);
CREATE TABLE IF NOT EXISTS split_expense_payers (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, expense_id TEXT NOT NULL, participant_id TEXT NOT NULL, amount_satang INTEGER NOT NULL CHECK(amount_satang > 0), FOREIGN KEY(expense_id) REFERENCES split_expenses(id) ON DELETE CASCADE, FOREIGN KEY(participant_id) REFERENCES split_participants(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS split_expense_shares (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, expense_id TEXT NOT NULL, participant_id TEXT NOT NULL, amount_satang INTEGER NOT NULL CHECK(amount_satang >= 0), percentage_basis_points INTEGER CHECK(percentage_basis_points BETWEEN 0 AND 10000), UNIQUE(expense_id,participant_id), FOREIGN KEY(expense_id) REFERENCES split_expenses(id) ON DELETE CASCADE, FOREIGN KEY(participant_id) REFERENCES split_participants(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS split_settlements (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, bill_id TEXT NOT NULL, from_participant_id TEXT NOT NULL, to_participant_id TEXT NOT NULL, amount_satang INTEGER NOT NULL CHECK(amount_satang > 0), paid_at TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', idempotency_key TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,idempotency_key), FOREIGN KEY(bill_id) REFERENCES split_bills(id) ON DELETE CASCADE, FOREIGN KEY(from_participant_id) REFERENCES split_participants(id) ON DELETE CASCADE, FOREIGN KEY(to_participant_id) REFERENCES split_participants(id) ON DELETE CASCADE, CHECK(from_participant_id != to_participant_id));
CREATE INDEX IF NOT EXISTS idx_split_settlements_bill ON split_settlements(user_id,bill_id,paid_at DESC);
CREATE TABLE IF NOT EXISTS bbq_visits (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, restaurant TEXT NOT NULL DEFAULT '', title TEXT NOT NULL DEFAULT '', visit_at TEXT NOT NULL, area TEXT NOT NULL DEFAULT '', friends_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(friends_json)), people_count INTEGER NOT NULL DEFAULT 1 CHECK(people_count > 0), total_satang INTEGER CHECK(total_satang >= 0), personal_satang INTEGER CHECK(personal_satang >= 0), rating INTEGER CHECK(rating BETWEEN 1 AND 5), menu TEXT NOT NULL DEFAULT '', memory TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_bbq_visits_owner_date ON bbq_visits(user_id,visit_at DESC);
CREATE TABLE IF NOT EXISTS bbq_photos (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, visit_id TEXT NOT NULL, storage_key TEXT NOT NULL, mime_type TEXT NOT NULL CHECK(mime_type IN ('image/jpeg','image/png','image/webp')), size_bytes INTEGER NOT NULL CHECK(size_bytes BETWEEN 1 AND 5242880), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(visit_id) REFERENCES bbq_visits(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_bbq_photos_owner_visit ON bbq_photos(user_id,visit_id);
CREATE TABLE IF NOT EXISTS bbq_bill_links (user_id TEXT NOT NULL, bill_id TEXT NOT NULL UNIQUE, visit_id TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,bill_id,visit_id), FOREIGN KEY(bill_id) REFERENCES split_bills(id) ON DELETE CASCADE, FOREIGN KEY(visit_id) REFERENCES bbq_visits(id) ON DELETE CASCADE);
